use vstd::prelude::*;

verus! {
    fn empty(n: u8) -> (result: Vec<f64>)
        requires
            n <= 255,
        ensures
            result.len() == n as usize,
    {
        let mut vec: Vec<f64> = Vec::new();
        let mut current_length: usize = 0;

        while current_length < n as usize
            invariant
                current_length <= n as usize,
                vec.len() == current_length,
                current_length <= 255,
            decreases n as usize - current_length,
        {
            vec.push(0.0); // We can push any value; here we use 0.0
            current_length = current_length + 1;
        }

        vec
    }
}

